import{c as s,Q as n,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"TSCM输入的矩阵乘","description":"","frontmatter":{},"headers":[{"level":1,"title":"TSCM输入的矩阵乘","slug":"tscm输入的矩阵乘"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/TSCM输入的矩阵乘.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/TSCM输入的矩阵乘.md"}'),t={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/TSCM输入的矩阵乘.md"};function p(i,a,r,c,o,m){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="tscm输入的矩阵乘" tabindex="-1">TSCM输入的矩阵乘 <a class="header-anchor" href="#tscm输入的矩阵乘" aria-label="Permalink to &quot;TSCM输入的矩阵乘&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>TSCM表示L1 Buffer空间对应的逻辑内存，L1 Buffer相关内容见<a href="./../../../../编程指南/硬件实现/基本架构.html#section123639375417">存储单元</a>，开发者可以自行管理TSCM以高效利用硬件资源。比如，开发者可缓存一份TSCM数据，在不同使用场景中灵活配置为Matmul操作的A矩阵、B矩阵或Bias偏置矩阵，实现内存复用与计算效率优化。在TSCM输入场景，用户管理整块TSCM内存空间，Matmul直接使用传入的TSCM内存地址，不进行Global Memory到TSCM的数据搬入。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>用户需要自定义数据搬入到TSCM及自定义管理的场景，即需要自定义实现数据搬入功能，如非连续搬入或对搬入数据进行预处理等。用户通过自定义管理TSCM可灵活配置MTE2流水，实现跨Matmul对象的全局<a href="./../../../../编程指南/概念原理和术语/性能优化技术原理/DoubleBuffer.html">DoubleBuffer</a>，MTE2相关内容见<a href="./../../../../编程指南/硬件实现/基本架构.html#section123639375417">搬运单元</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>设置为TSCM输入的矩阵必须在TSCM中全载，全载即全部的矩阵数据同时搬入及保持在TSCM中。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_tscm" target="_blank" rel="noreferrer">自定义数据来源为GM的TSCM输入的Matmul算子样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TQue&lt;TPosition::A1, 1&gt; scm; // 队列逻辑位置A1，队列深度为1</span></span>
<span class="line"><span>pipe-&gt;InitBuffer(scm, 1, tiling.M * tiling.Ka * sizeof(A_T)); </span></span>
<span class="line"><span>// A_TYPE的TPosition为TSCM， B_TYPE的TPosition为GM</span></span>
<span class="line"><span>Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE&gt; mm1;</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1);</span></span>
<span class="line"><span>mm1.Init(&amp;tiling);</span></span>
<span class="line"><span>// 自定义A矩阵GM到TSCM的搬运</span></span>
<span class="line"><span>auto scmTensor = scm.AllocTensor&lt;A_T&gt;();</span></span>
<span class="line"><span>DataCopy(scmTensor, gm_a, tiling.M * tiling.Ka);</span></span>
<span class="line"><span>scm.EnQue(scmTensor);</span></span>
<span class="line"><span>LocalTensor&lt;A_T&gt; scmLocal = scm.DeQue&lt;A_T&gt;();</span></span>
<span class="line"><span>// A矩阵设置为TSCM输入，B矩阵为GM输入</span></span>
<span class="line"><span>mm1.SetTensorA(scmLocal);</span></span>
<span class="line"><span>mm1.SetTensorB(gm_b);</span></span>
<span class="line"><span>mm1.SetBias(gm_bias);</span></span>
<span class="line"><span>mm1.IterateAll(gm_c);</span></span>
<span class="line"><span>scm.FreeTensor(scmLocal);</span></span></code></pre></div>`,10)])])}const u=s(t,[["render",p]]);export{_ as __pageData,u as default};
